package com.library.ui; import com.library.model.*; import com.library.service.ReportService; import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*;
public class ReportFrame extends JFrame { private final ReportService reports=new ReportService(); public ReportFrame(){super("Library Reports");setSize(1000,560);setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JTabbedPane tabs=new JTabbedPane();tabs.add("Books",books());tabs.add("Members",members());tabs.add("Transactions",transactions());add(tabs);} private JComponent books(){DefaultTableModel m=new DefaultTableModel(new String[]{"ISBN","Book","Author","Category","Qty","Available","Status"},0);for(Book b:reports.books(""))m.addRow(new Object[]{b.getIsbn(),b.getBookName(),b.getAuthor(),b.getCategoryName(),b.getQuantity(),b.getAvailableQuantity(),b.getStatus()});return new JScrollPane(new JTable(m));} private JComponent members(){DefaultTableModel m=new DefaultTableModel(new String[]{"ID","Name","Email","Course","Semester","Status"},0);for(Member x:reports.members())m.addRow(new Object[]{x.getMemberId(),x.getName(),x.getEmail(),x.getCourse(),x.getSemester(),x.getStatus()});return new JScrollPane(new JTable(m));} private JComponent transactions(){DefaultTableModel m=new DefaultTableModel(new String[]{"ID","Member","Book","Due","Return","Fine","Status"},0);for(Transaction x:reports.transactions())m.addRow(new Object[]{x.getTransactionId(),x.getMemberName(),x.getBookName(),x.getDueDate(),x.getReturnDate(),UI.rupee(x.getFine()),x.getStatus()});return new JScrollPane(new JTable(m));} }
